package local.proskurnin.preview;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.drawable.*;import java.util.*;
public class AppKeySettingsActivity extends Activity {
 final Handler handler=new Handler();Button enabled;final Button[] rows=new Button[4];AlertDialog learn;boolean visible;
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 Button button(LinearLayout root,String text,Runnable action){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setTextSize(16);b.setTextColor(0xffe7edf6);b.setGravity(Gravity.CENTER_VERTICAL|Gravity.LEFT);b.setPadding(dp(16),dp(4),dp(16),dp(4));StateListDrawable states=new StateListDrawable();for(boolean focus:new boolean[]{true,false}){GradientDrawable d=new GradientDrawable();d.setColor(focus?0xff344b65:0xff192638);d.setCornerRadius(dp(10));if(focus)d.setStroke(dp(2),0xffbdd8f5);states.addState(focus?new int[]{android.R.attr.state_focused}:new int[]{},d);}b.setBackground(states);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(56));p.bottomMargin=dp(7);root.addView(b,p);b.setOnClickListener(v->action.run());return b;}
 public void onCreate(Bundle state){super.onCreate(state);getWindow().getDecorView().setSystemUiVisibility(5894);getWindow().setBackgroundDrawable(new ColorDrawable(0xff0d1420));ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(30),dp(20),dp(30),dp(16));scroll.addView(root);setContentView(scroll);TextView title=new TextView(this);title.setText("Кнопки приложений на пульте");title.setTextSize(28);title.setTextColor(0xffeeeeee);root.addView(title);TextView note=new TextView(this);note.setText("Выберите кнопку, определите её нажатием и назначьте действия.\nДвойное нажатие — до 0,45 с. До обучения кнопка работает как раньше.");note.setTextColor(0xff9eafc7);note.setTextSize(14);note.setPadding(0,dp(8),0,dp(12));root.addView(note);
  enabled=button(root,"",()->{AppKeys.prefs(this).edit().putBoolean("appkeys_enabled",!AppKeys.enabled(this)).apply();refresh();});for(int i=0;i<4;i++){final int slot=i;rows[i]=button(root,"",()->edit(slot));}button(root,"Служба кнопок · специальные возможности",()->startActivity(new Intent("android.settings.ACCESSIBILITY_SETTINGS")));button(root,"Назад",()->finish());refresh();enabled.requestFocus();
 }
 void refresh(){enabled.setText("Свои назначения: "+(AppKeys.enabled(this)?"включены":"выключены · штатные кнопки"));for(int i=0;i<4;i++){boolean learned=!AppKeys.prefs(this).getString(AppKeys.key(i,"binding"),"").isEmpty();rows[i].setText(AppKeys.NAMES[i]+(learned?"":" · нужно определить кнопку")+"\n1× "+AppKeys.label(this,AppKeys.action(this,i,false))+"    2× "+AppKeys.label(this,AppKeys.action(this,i,true)));}}
 void edit(int slot){new AlertDialog.Builder(this).setTitle(AppKeys.NAMES[slot]).setItems(new String[]{"Определить кнопку на пульте","Одиночное: "+AppKeys.label(this,AppKeys.action(this,slot,false)),"Двойное: "+AppKeys.label(this,AppKeys.action(this,slot,true)),"Сбросить эту кнопку"},(d,n)->{if(n==0)learn(slot);else if(n==1||n==2)choose(slot,n==2);else new AlertDialog.Builder(this).setMessage("Вернуть штатное поведение кнопки "+AppKeys.NAMES[slot]+"?").setPositiveButton("Сбросить",(a,b)->{AppKeys.prefs(this).edit().remove(AppKeys.key(slot,"binding")).remove(AppKeys.key(slot,"single")).remove(AppKeys.key(slot,"double")).apply();refresh();}).setNegativeButton("Отмена",null).show();}).setNegativeButton("Закрыть",null).show();}
 void choose(int slot,boolean twice){String[] actions={"app","home","movies","chat","sources","settings","none"};String[] labels={"Выбрать приложение…","Главный экран","Подбор фильма · голос","Диалог AI · голос","Источники","Настройки ТВ","Ничего"};new AlertDialog.Builder(this).setTitle((twice?"Двойное":"Одиночное")+" · "+AppKeys.NAMES[slot]).setItems(labels,(d,n)->{if(n==0)chooseApp(slot,twice);else save(slot,twice,actions[n]);}).setNegativeButton("Назад",null).show();}
 void chooseApp(int slot,boolean twice){LinkedHashMap<String,String> apps=AppKeys.apps(this);String[] packages=apps.keySet().toArray(new String[0]),names=apps.values().toArray(new String[0]);new AlertDialog.Builder(this).setTitle("Запустить приложение").setItems(names,(d,n)->save(slot,twice,"app:"+packages[n])).setNegativeButton("Назад",null).show();}
 void save(int slot,boolean twice,String value){AppKeys.prefs(this).edit().putString(AppKeys.key(slot,twice?"double":"single"),value).apply();refresh();}
 void learn(int slot){AppKeyLearning.cancel();learn=new AlertDialog.Builder(this).setTitle("Нажмите кнопку «"+AppKeys.NAMES[slot]+"»").setMessage("Один раз нажмите нужную кнопку приложения. Ожидание — 20 секунд. Back — отмена.\n\nЕсли откроется штатное приложение, прошивка перехватила кнопку: назначение не будет сохранено.").setNegativeButton("Отмена",null).create();learn.setOnDismissListener(d->{AppKeyLearning.cancel();handler.removeCallbacksAndMessages(null);learn=null;});learn.show();AppKeyLearning.begin(id->{if(!visible)return;if(learn!=null)learn.dismiss();int existing=AppKeys.slot(this,id);if(existing>=0&&existing!=slot){new AlertDialog.Builder(this).setMessage("Эта кнопка уже назначена как «"+AppKeys.NAMES[existing]+"». Сначала сбросьте её назначение.").setPositiveButton("Понятно",null).show();return;}new AlertDialog.Builder(this).setTitle("Кнопка распознана").setMessage("Использовать её для настроек «"+AppKeys.NAMES[slot]+"»?").setPositiveButton("Назначить",(d,n)->{AppKeys.prefs(this).edit().putString(AppKeys.key(slot,"binding"),id).apply();refresh();}).setNegativeButton("Отмена",null).show();});handler.postDelayed(()->{if(learn!=null){learn.dismiss();if(visible)new AlertDialog.Builder(this).setMessage("Кнопка не получена. Проверьте службу кнопок в специальных возможностях. Если прошивка забирает нажатие раньше, нужна отдельная диагностика.").setPositiveButton("Понятно",null).show();}},20000);}
 @Override public boolean dispatchKeyEvent(KeyEvent event){if(AppKeyLearning.event(event))return true;return super.dispatchKeyEvent(event);}
 protected void onResume(){super.onResume();visible=true;refresh();}
 protected void onPause(){visible=false;if(learn!=null)learn.dismiss();AppKeyLearning.cancel();handler.removeCallbacksAndMessages(null);super.onPause();}
 protected void onDestroy(){AppKeyLearning.cancel();handler.removeCallbacksAndMessages(null);super.onDestroy();}
}
